1→//! op-mcp: MCP protocol and tool-runtime library.
//!
//! The crate owns no production listener binary. `op-grpc-bridge` owns the
//! authenticated external MCP frontend and uses these protocol/tool primitives
//! for embedded execution. Library consumers can compose the following modes:
//! - **Compact**: 5 meta-tools with per-request lazy tool loading (recommended for LLMs)
//! - **Agents**: Always-on cognitive agents (memory, sequential_thinking, etc.)
//! - **Full**: All tools directly exposed (may hit client limits)
//! - **BlobSchema**: sealed plugin-blob catalog (schema/manifest/methods)
10→//!
//! Supports multiple transports:
//! - Stdio (standard MCP transport)
//! - HTTP (REST endpoints)
//! - SSE (Server-Sent Events)
//! - HTTP+SSE (bidirectional)
//! - WebSocket (full duplex)
//! - gRPC (high-performance RPC)

pub mod agents_server;
20→pub mod blob_schema;
pub mod cognitive_bridge;
pub mod compact;
pub mod external_client;
pub mod protocol;
pub mod resources;
pub mod server;
pub mod transport;

pub mod tool_registry;
30→
#[cfg(feature = "grpc")]
pub mod grpc;

// Re-exports
pub use agents_server::AgentsServer;
pub use blob_schema::BlobSchemaExecutor;
pub use compact::{
    CompactServer, PrewarmedOpToolsExecutor, SessionContext, run_compact_stdio_server,
    run_compact_unix_server,
40→};
pub use external_client::{
    AuthMethod, ExternalMcpClient, ExternalMcpConfig, ExternalMcpManager, ExternalTool,
};
pub use op_core::SecurityLevel;
pub use protocol::{JsonRpcError, McpError, McpRequest, McpResponse};
pub use resources::ResourceRegistry;
pub use server::{DefaultToolExecutor, McpServer, McpServerConfig, ToolExecutor, ToolInfo};
pub use tool_registry::{Tool, ToolRegistry};
pub use transport::{
50→    HttpSseTransport, HttpTransport, SseTransport, StdioTransport, Transport, WebSocketTransport,
};

#[cfg(feature = "grpc")]
pub use grpc::GrpcTransport;

/// Protocol version
pub const PROTOCOL_VERSION: &str = "2024-11-05";

/// Server info
60→pub const SERVER_NAME: &str = "op-mcp";
pub const SERVER_VERSION: &str = env!("CARGO_PKG_VERSION");

/// Server mode
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ServerMode {
    /// 5 meta-tools for tool discovery and response
    Compact,
    /// Always-on cognitive agents
    Agents,
70→    /// All tools directly exposed
    Full,
    /// Cognitive tools sourced from op-grpc-bridge (fan-in proxy).
    ///
    /// One authenticated caller fronting the bridge, so MCP clients need no
    /// credential and the cognitive store keeps a single writer.
    Cognitive,
    /// Read-only sealed blob catalog: PluginSchema, manifest, methods.
    BlobSchema,
}
80→
impl std::fmt::Display for ServerMode {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            ServerMode::Compact => write!(f, "compact"),
            ServerMode::Agents => write!(f, "agents"),
            ServerMode::Full => write!(f, "full"),
            ServerMode::Cognitive => write!(f, "cognitive"),
            ServerMode::BlobSchema => write!(f, "blob-schema"),
        }
90→    }
}

impl std::str::FromStr for ServerMode {
    type Err = String;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        match s.to_lowercase().as_str() {
            "compact" => Ok(ServerMode::Compact),
            "agents" => Ok(ServerMode::Agents),
100→            "full" | "standard" => Ok(ServerMode::Full),
            "cognitive" | "bridge" => Ok(ServerMode::Cognitive),
            "blob" | "blob-schema" | "schema" => Ok(ServerMode::BlobSchema),
            _ => Err(format!("Unknown server mode: {}", s)),
        }
    }
}

1→//! Bridge-backed tool executor: the fan-in proxy's engine.
//!
//! Sources its tool list and dispatches every call through `op-grpc-bridge` rather
//! than opening the cognitive store directly. That matters for three reasons, each
//! measured rather than assumed:
//!
//! 1. **One CozoDB writer.** The bridge owns the persistent `CognitiveServer`.
//!    Historically, clients spawning the retired `op-cognitive --stdio`
//!    raced for its file lock and lost with `Resource temporarily unavailable`.
10→//!    Routing through the bridge leaves exactly one owner.
//!
//! 2. **Enforcement.** The direct stdio path bypasses the method gate, argument
//!    validation, capability check and event chain. Every call made here passes all
//!    four and lands in the event chain with an `event_id`.
//!
//! 3. **One authenticated caller.** This process holds the identity, so individual
//!    MCP clients carry no credential material and capability can be scoped per
//!    client without touching the sealed schema.
//!
20→//! Transport is D-Bus `org.opdbus.v1.PluginV1.Call` on the `cognitive` plugin —
//! the only interface and bus name in play. `list_tools` populates the registry;
//! `invoke_tool` dispatches.
//!
//! OSCAL subid: exp.service.cognitive.fanin-proxy@v1

use crate::server::{ToolExecutor, ToolInfo};
use anyhow::{Context, Result, anyhow};
use simd_json::prelude::*;
use simd_json::{OwnedValue as Value, json};
30→use tokio::sync::RwLock;

/// Bus name owned by op-grpc-bridge. The only legal well-known name.
const BRIDGE_BUS_NAME: &str = "org.opdbus.v1.plugins";
/// The single canonical plugin interface.
const PLUGIN_INTERFACE: &str = "org.opdbus.v1.PluginV1";
/// Object path for the cognitive plugin.
const COGNITIVE_OBJECT_PATH: &str = "/org/opdbus/v1/plugins/cognitive";

/// Session bus address; matches the bridge's own default.
40→fn session_bus_address() -> String {
    std::env::var("DBUS_SESSION_BUS_ADDRESS")
        .unwrap_or_else(|_| "unix:path=/run/opdbus/session-bus.sock".to_string())
}

pub struct BridgeToolExecutor {
    connection: zbus::Connection,
    /// Cached tool list. The registry is populated at runtime on the cognitive side,
    /// so this is refreshed on demand rather than assumed static.
    tools: RwLock<Vec<ToolInfo>>,
50→}

impl BridgeToolExecutor {
    pub async fn connect() -> Result<Self> {
        let address = session_bus_address();
        let connection = zbus::connection::Builder::address(address.as_str())
            .with_context(|| format!("invalid session bus address: {address}"))?
            .build()
            .await
            .with_context(|| format!("connecting to session bus at {address}"))?;
60→
        let executor = Self {
            connection,
            tools: RwLock::new(Vec::new()),
        };
        executor.refresh().await?;
        Ok(executor)
    }

    /// Invoke one schema method on the cognitive plugin through the bridge.
70→    ///
    /// Returns the `result` payload, unwrapping the bridge's accountability envelope
    /// (`success`, `event_id`, `event_hash`, `result`). A missing `result` is an
    /// error rather than an empty success, so a silent contract change surfaces.
    async fn call_method(&self, method: &str, json_args: &str) -> Result<Value> {
        let catalog = std::env::var_os("OP_BLOB_CATALOG_DIR").map(std::path::PathBuf::from)
            .unwrap_or_else(|| op_blob::catalog::DEFAULT_SHM_DIR.into());
        let (source_hash, schema) = op_blob::catalog::read_plugin_state_store_contract(&catalog, "cognitive")
            .context("cognitive source contract is unavailable")?;
        anyhow::ensure!(schema.methods.contains_key(method), "cognitive method is not declared");
80→        let reply = self
            .connection
            .call_method(
                Some(BRIDGE_BUS_NAME),
                COGNITIVE_OBJECT_PATH,
                Some(PLUGIN_INTERFACE),
                "Call",
                &(method, json_args, source_hash.as_str()),
            )
            .await
90→            .with_context(|| format!("bridge PluginV1.Call({method})"))?;

        let body: String = reply
            .body()
            .deserialize()
            .context("bridge returned a non-string body")?;

        let mut body_bytes = body.clone().into_bytes();
        let envelope: Value = simd_json::to_owned_value(&mut body_bytes)
            .map_err(|e| anyhow!("bridge returned invalid JSON for {method}: {e}: {body}"))?;
100→
        envelope
            .get("result")
            .cloned()
            .ok_or_else(|| anyhow!("bridge envelope for {method} carried no 'result': {body}"))
    }

    /// Re-read the tool list from the live registry via the bridge.
    async fn refresh(&self) -> Result<usize> {
        // list_tools takes no arguments; the schema types it as an empty object, so
110→        // `{}` validates where a bare `null` previously did not.
        let result = self.call_method("list_tools", "{}").await?;

        let entries = result
            .get("tools")
            .and_then(|v: &Value| v.as_array())
