    let address_host = host
        .strip_prefix('[')
210→        .and_then(|value| value.strip_suffix(']'))
        .unwrap_or(host);
    let is_loopback = address_host.eq_ignore_ascii_case("localhost")
        || address_host
            .parse::<std::net::IpAddr>()
            .is_ok_and(|address| address.is_loopback());
    if !is_loopback {
